export type IconName = keyof typeof PATHS;

/** icons whose Figma export uses an even-odd fill (a hole cut out of the shape) */
const EVENODD = new Set<IconName>(['new_chat', 'search', 'more_horiz']);

export function Icon({ name, size = 24 }: { name: IconName; size?: number }) {
  return (
    <svg className="icon" width={size} height={size} viewBox="0 0 24 24" fill="currentColor" aria-hidden focusable="false">
      {PATHS[name].map((d, i) => (
        <path key={i} d={d} fillRule={EVENODD.has(name) ? 'evenodd' : undefined} />
      ))}
    </svg>
  );
}
